  "settings.magicPrompts.page.block.instructions": "Инструкции",
  "settings.magicPrompts.page.group.gitCommitGenerate.title": "Генерация сообщения коммита",
  "settings.magicPrompts.page.group.gitCommitGenerate.description": "Подсказки для генерации сообщения коммита: видимое сообщение пользователя + скрытые инструкции.",
  "settings.magicPrompts.page.group.gitPrGenerate.title": "Генерация PR",
  "settings.magicPrompts.page.group.gitPrGenerate.description": "Подсказки, используемые для генерации заголовка PR/body: видимое сообщение пользователя + скрытые инструкции.",
  "settings.magicPrompts.page.group.walkthrough.title": "Разбор",
  "settings.magicPrompts.page.group.walkthrough.description": "Ваши предпочтения для разбора изменений: тон, акценты, на чём остановиться, а что опустить. Они добавляются к промпту разбора и не могут изменить его формат. Пусто — без предпочтений.",
  "settings.magicPrompts.page.group.gitConflictResolve.title": "Разрешение конфликтов слияния/перебазирования",
  "settings.magicPrompts.page.group.gitConflictResolve.description": "Подсказки, используемые при разрешении конфликтов merge/rebase с AI.",
  "settings.magicPrompts.page.group.gitCherrypickConflictResolve.title": "Выборочное разрешение конфликтов",
  "settings.magicPrompts.page.group.gitCherrypickConflictResolve.description": "Подсказки, используемые при разрешении конфликтов выбора в потоке интеграции.",
  "settings.magicPrompts.page.group.planImprove.title": "Улучшить план",
  "settings.magicPrompts.page.group.planImprove.description": "Скрытый запрос, используемый при отправке сохраненного плана в поток улучшения.",
  "settings.magicPrompts.page.group.planTodo.title": "Планирование дел",
  "settings.magicPrompts.page.group.planTodo.description": "Скрытая подсказка, используемая при отправке задачи в новую сессию планирования.",
  "settings.magicPrompts.page.group.planImplement.title": "Реализация плана",
  "settings.magicPrompts.page.group.planImplement.description": "Скрытый запрос, используемый при отправке сохранённого плана в поток реализации.",
  "settings.magicPrompts.page.group.sessionSummary.title": "Резюме сессии",
  "settings.magicPrompts.page.group.sessionSummary.description": "Подсказки, используемые slash-командой /summary: видимое сообщение пользователя + скрытые инструкции. Неразрушающий — не сжимает историю сессий.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.title": "Обзор рабочего пространства",
  "settings.magicPrompts.page.group.sessionExplore.title": "Обзор кодовой базы",
  "settings.magicPrompts.page.group.sessionExplore.description": "Подсказки, используемые slash-командой /explore: видимое сообщение пользователя + скрытые инструкции. Исследует репозиторий и дает структурированную ориентацию — общую картину, основные модули, способы их подключения и с чего начать — а не дамп пофайлов.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.description": "Подсказки, используемые slash-командой /workspace-review: видимое сообщение пользователя + скрытые инструкции. Проверяет разницу в рабочей области на предмет того, достигает ли она своей цели, является ли она правильной и адекватной, классифицируя результаты по серьёзности. Инструкции также управляют сессиями ревью, включая автоматический цикл ревью.",
  "settings.magicPrompts.page.group.sessionFeaturePlan.title": "Планирование функций",
  "settings.magicPrompts.page.group.sessionFeaturePlan.description": "Подсказки, используемые slash-командой /plan-feature: видимое сообщение пользователя + скрытые инструкции. Запускает управляемый диалог, в ходе которого исследуется код и небольшими порциями задаются уточняющие вопросы, прежде чем составить план реализации.",
  "settings.magicPrompts.page.group.sessionCatchUp.title": "Настигнуть",
  "settings.magicPrompts.page.group.sessionCatchUp.description": "Промпты для slash-команды /catch-up: видимое сообщение пользователя и скрытые инструкции. Собирают контекст по ветке: её коммиты, PR и незакоммиченные изменения, чтобы понять, чем вы занимались, а затем дать краткую понятную сводку и следующий шаг с фокусом на продукт.",
  "settings.magicPrompts.page.group.sessionDebug.title": "Отладка",
  "settings.magicPrompts.page.group.sessionDebug.description": "Подсказки, используемые slash-командой /debug: видимое сообщение пользователя + скрытые инструкции. Запускает управляемое расследование первопричин — фиксирует симптом, формирует гипотезы, сверяет их с кодом и подтверждает причину, прежде чем предлагать исправление.",
  "settings.magicPrompts.page.group.sessionWeigh.title": "Варианты взвешивания",
  "settings.magicPrompts.page.group.sessionWeigh.description": "Подсказки, используемые slash-командой /weigh: видимое сообщение пользователя + скрытые инструкции. Исследует код, затем предлагает 2–3 различных подхода с компромиссами и рекомендациями — без написания плана или кода.",
  "settings.magicPrompts.page.group.sessionFusion.title": "Слияние",
  "settings.magicPrompts.page.group.sessionFusion.description": "Подсказки, используемые при объединении выходных данных multi-run в один окончательный ответ: видимое сообщение пользователя + скрытые инструкции перед исходными результатами.",
