  "settings.integrations.extensionCatalog.resourceMonitor.name": "Монитор ресурсов",
  "settings.mcp.page.advanced.codemode": "Code Mode",
  "settings.mcp.page.advanced.codemodeHint": "Обычно каждый инструмент MCP-сервера становится отдельным инструментом, который модель видит и вызывает по одному. В Code Mode модель получает один инструмент, запускающий короткий скрипт, а скрипт вызывает инструменты этого сервера как функции. Так контекст остаётся маленьким, когда у сервера много инструментов, и несколько вызовов умещаются в один шаг. Маленькие модели пишут такие скрипты менее надёжно, поэтому режим можно выключать для каждого сервера.",
  "settings.mcp.page.advanced.codemodeDefaultHint": "По умолчанию решает OpenCode: Code Mode включён для большинства серверов, но OpenCode отключает его для серверов с собственным Code Mode, например executor.sh, а у PostHog запрашивает простые инструменты вместо его собственного Code Mode.",
  "settings.mcp.page.advanced.codemodeOption.default": "По умолчанию (решает OpenCode)",
