  "settings.mcp.page.advanced.oauthMetadataUrlPlaceholder": "https://example.com/.well-known/oauth-authorization-server",
  "settings.mcp.page.advanced.protocol": "Протокол",
  "settings.mcp.page.advanced.protocolHint": "Legacy открывает соединение рукопожатием initialize и говорит на ревизиях протокола до 2025-11-25. Auto пробует ревизию 2026-07-28 и откатывается к legacy, если сервер её не поддерживает. 2026-07-28 требует эту ревизию и иначе завершается ошибкой.",
