  "settings.openchamber.sessionWork.info": "Блок в боковой панели, под «Чатами», для сессий, в которых вы работаете. Сессия попадает туда, когда вы отправляете в ней сообщение, остаётся и в своём проекте, а уходит, когда вы отметите её готовой: наведите курсор и нажмите галочку или используйте меню сессии. Когда ход выглядит как конец работы, галочка становится серой — как подсказка.",
  "settings.openchamber.sessionWork.field.enabled": "Показывать сессии в работе",
  "settings.openchamber.desktopNetwork.field.enterpriseBlocked": "Корпоративный режим оставляет OpenChamber на этом компьютере. Ваш администратор может разрешить доступ в сеть.",
  "settings.openchamber.spaces.idleStop.enabled": "Останавливать простаивающие пространства",
  "settings.openchamber.spaces.idleStop.enabledAria": "Останавливать простаивающие пространства",
  "settings.openchamber.spaces.idleStop.enabledInfo": "Останавливает пространство без активности. Файлы сохраняются. Работает даже при закрытом OpenChamber.",
  "settings.openchamber.spaces.idleStop.after": "Останавливать через",
