  "settings.openchamber.spaces.idleStop.loadFailed": "Не удалось загрузить эту настройку.",
  "settings.openchamber.tools.field.agentControlToolSummary": "Создавайте сессии и рабочие копии и управляйте ими.",
  "settings.openchamber.tools.field.agentScheduleTool": "Инструмент расписания агента",
  "settings.openchamber.tools.field.agentScheduleToolAria": "Включить инструмент расписания агента",
  "settings.openchamber.tools.field.agentScheduleToolInfo": "Агенты могут запускать промпт ежедневно, еженедельно, один раз или по cron-расписанию, а также изменять, запускать, приостанавливать и удалять задачи.",
  "settings.openchamber.tools.field.agentScheduleToolSummary": "Создавайте и запускайте задачи по расписанию.",
  "settings.openchamber.tools.field.agentWebToolSummary": "Открытие, чтение и переход по страницам в панели браузера.",
  "settings.openchamber.tools.field.agentToolsCodeMode": "Выполнять через Code Mode",
  "settings.openchamber.tools.field.agentToolsCodeModeAria": "Запуск инструментов OpenChamber через Code Mode",
  "settings.openchamber.tools.field.agentToolsCodeModeInfo": "Выкл.: модель видит каждый инструмент напрямую. Вкл.: они скрыты за одним инструментом, который выполняет короткий скрипт и вызывает их. Экономит немного контекста, но модель может их не заметить, особенно небольшая. Инструмент отрисовки всегда остаётся прямым, потому что страницу чата он рисует собственным вызовом.",
  "settings.openchamber.keyboardShortcuts.action.open_document_symbols.label": "Перейти к символу в файле (редактор файлов)",
  "settings.openchamber.keyboardShortcuts.action.session_history_back.label": "Назад по истории сессии",
  "settings.openchamber.keyboardShortcuts.action.session_history_forward.label": "Вперёд по истории сессии",
  "settings.openchamber.keyboardShortcuts.action.archive_current_session.label": "Архивировать текущую сессию",
  "settings.openchamber.keyboardShortcuts.action.background_session_work.label": "Перевести работу в фон",
  "settings.openchamber.visual.goal.checkerLabel": "Проверка прогресса",
  "settings.openchamber.visual.goal.checkerInfo": "После каждого хода отчёт агента читается, чтобы решить, достигнута ли цель, ждёт ли она вас или должна продолжаться. Jev решает меньше чем за секунду; небольшая модель работает на провайдере самой сессии и подключается также тогда, когда Jev не может ответить.",
  "settings.openchamber.visual.goal.checker.smallModel": "Небольшая модель",
  "settings.openchamber.visual.goal.checker.viaSmallModel": "Каждый ход проверяется небольшой моделью.",
  "settings.openchamber.visual.goal.checker.jevMissing": "Для Jev не настроен провайдер классификации, поэтому каждый ход проверяет небольшая модель.",
  "settings.openchamber.visual.goal.checker.smallModelLink": "Настройки небольшой модели",
  "settings.openchamber.mergedWorktreeCleanup.title": "После влития PR",
  "settings.openchamber.mergedWorktreeCleanup.info": "Использует статус PR, который боковая панель уже показывает. Ничего не происходит, пока агент работает в рабочей копии или открыта одна из её сессий.",
  "settings.openchamber.mergedWorktreeCleanup.field.enable": "Архивировать рабочую копию после влития её PR",
  "settings.openchamber.mergedWorktreeCleanup.field.enableDescription": "Рабочая копия и её локальная ветка удаляются, когда в ней нет незакоммиченных изменений и коммитов, отсутствующих во влитом PR. До этого сессии архивируются, а рабочая копия остаётся.",
  "settings.openchamber.opencodeCli.field.pinnedByAdministrator": "Ваш администратор задал этот путь, поэтому OpenChamber всегда запускает OpenCode из него.",
  "settings.openchamber.visual.field.webFontsEnterprise": "В корпоративном режиме используются системные шрифты: остальные загружаются с публичного CDN.",
  "settings.openchamber.visual.goal.maxTurnsLabel": "Лимит ходов",
  "settings.openchamber.visual.goal.maxTurnsInfo": "После такого числа автоматических ходов цель останавливается и возвращает управление вам — сделано или нет. По умолчанию 20.",
  "settings.openchamber.visual.goal.maxTurnsResetAria": "Сбросить лимит ходов на 20",
  "settings.openchamber.visual.field.expandReasoningWhileStreaming": "Раскрывать рассуждения во время генерации",
  "settings.openchamber.visual.field.expandReasoningWhileStreamingAria": "Раскрывать блоки рассуждений, пока модель думает",
  "settings.openchamber.visual.field.expandReasoningWhileStreamingInfo": "Показывает мысли модели и сводку сжатия по мере их поступления. Когда выключено, они остаются свёрнутыми и раскрываются по щелчку.",
  "settings.openchamber.visual.field.tableCellWrap": "Перенос в ячейках таблиц",
  "settings.openchamber.visual.field.tableCellWrapAria": "Переносить текст в ячейках таблиц",
  "settings.openchamber.visual.field.tableCellWrapInfo": "Таблицы укладываются в ширину чата, а длинный текст в ячейках переносится вместо горизонтальной прокрутки.",
  "settings.openchamber.visual.field.copyMessagesAsPlainText": "Копировать сообщения как обычный текст",
  "settings.openchamber.visual.field.copyMessagesAsPlainTextAria": "Копировать сообщения как обычный текст",
