  "settings.openchamber.visual.field.layoutAnimationsAria": "Анимировать боковую панель и панели вокруг чата при открытии и закрытии",
  "settings.openchamber.visual.field.layoutAnimationsInfo": "Боковая панель, панели вокруг чата и карточка статуса работы плавно выезжают при открытии и закрытии. Выключите, чтобы показывать и скрывать их сразу.",
  "settings.openchamber.visual.option.fileTreeSide.left": "Слева",
  "settings.openchamber.visual.option.fileTreeSide.right": "Справа",
  "settings.openchamber.visual.field.openLinksInBrowserPanel": "Открывать ссылки во встроенном браузере",
  "settings.openchamber.visual.field.openLinksInBrowserPanelInfo": "Ссылки в чате открываются во вкладке браузера рядом с чатом. Cmd+клик или Ctrl+клик открывает их в браузере по умолчанию.",
  "settings.openchamber.visual.field.liveBrowserTabs": "Сколько вкладок браузера держать загруженными",
  "settings.openchamber.visual.field.liveBrowserTabsInfo": "Вкладки браузера во всех проектах остаются загруженными в указанном количестве, чтобы при возврате страница была в том же состоянии. Более старые вкладки перезагружаются при открытии. Каждая загруженная вкладка занимает память.",
  "settings.openchamber.visual.field.liveBrowserTabsUnit": "вкладок",
  "settings.openchamber.visual.field.openTrackerLinksOnBoard": "Открывать issue и pull request в OpenChamber",
  "settings.openchamber.visual.field.openTrackerLinksOnBoardInfo": "Ссылки на issue в GitHub и GitLab, pull request и merge request, а также issue в Linear открываются в трекере рядом с чатом, если их проект открыт здесь, а на телефоне — на доске «Issues and PRs». Cmd+клик или Ctrl+клик открывает саму ссылку.",
  "settings.openchamber.appLinks.empty": "На этом устройстве нет доверенных ссылок приложений. При открытии ссылки выберите «Доверить и открыть», чтобы добавить её сюда.",
  "settings.openchamber.tools.browserProvider.info": "OpenChamber Web — это панель браузера настольного приложения. Расширение браузера работает на сервере, поэтому агенты могут просматривать страницы без открытого настольного приложения.",
  "settings.openchamber.tools.field.agentMemoryToolInfo": "Агенты видят только заголовки записей и открывают запись, когда она уместна. Отключение также скрывает вкладку «Память».",
  "settings.openchamber.tools.field.agentMemoryToolSummary": "Между сессиями помнит, что верно о вас и о каждом проекте.",
  "settings.openchamber.tools.field.agentNotifyToolSummary": "Пусть агенты сообщают вам, когда работа готова или они застряли.",
  "settings.openchamber.tools.field.agentWorktreeMoveInfo": "Когда новая задача попадает на ветку, где уже есть pull request или изменения, которых агент не делал, агент переносит сессию в новую рабочую копию от ветки по умолчанию и сообщает об этом одной строкой. Выкл.: сначала спрашивает.",
  "settings.openchamber.tools.field.agentKnowledgeTool": "Инструмент знаний о проекте",
  "settings.openchamber.tools.field.agentKnowledgeToolAria": "Инструмент знаний о проекте",
  "settings.openchamber.tools.field.agentKnowledgeToolInfo": "Агенты работают с теми же элементами, что вы видите на панели «Знания о проекте».",
  "settings.openchamber.tools.field.agentKnowledgeToolSummary": "Разрешить агентам читать и обновлять заметки, задачи и планы проекта.",
  "settings.openchamber.tools.field.agentRenderTool": "Инструмент визуализации агента",
  "settings.openchamber.tools.field.agentRenderToolAria": "Инструмент визуализации агента",
  "settings.openchamber.tools.field.agentRenderToolInfo": "Страницы работают в изолированном пространстве без доступа к вашим сессиям и файлам. Ссылки открываются в вашем браузере.",
  "settings.openchamber.tools.field.agentRenderToolSummary": "Разрешить агентам показывать графики, таблицы, диаграммы и макеты интерфейса прямо в чате и предлагать выбрать вариант там же.",
  "settings.openchamber.defaults.field.sessionWarmingInfo": "Некоторые провайдеры забывают кэшированный контекст разговора после нескольких минут молчания, поэтому следующее сообщение обрабатывается медленнее и стоит дороже. С включённой опцией OpenChamber отправляет крошечный запрос «OK» каждые 4 минуты, пока сессия простаивает, — до 30 минут после вашего последнего сообщения. Каждый пинг тарифицируется как небольшой запрос. Применяется ко всем проектам.",
  "settings.openchamber.spaces.turnOff.stillRunning": "Не удалось остановить «{name}»: {reason}",
